cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check warranties table schema and data for our item/order
const cols = db.prepare(\"PRAGMA table_info(warranties)\").all();
console.log('Warranties columns:', cols.map(c => c.name + ' (' + c.type + ')'));

const warranties = db.prepare(\"SELECT * FROM warranties WHERE item_id = 'ITEM-E5801A' OR order_id = 'ORD-E0E671' OR order_id = '#W0000000'\").all();
console.log('Warranties matching item/order:', warranties);

// Broader search
const allW = db.prepare(\"SELECT * FROM warranties\").all();
console.log('All warranties (' + allW.length + '):', JSON.stringify(allW, null, 2));
"

