cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check reminders table schema
const cols = db.prepare(\"PRAGMA table_info(ts_reminders)\").all();
console.log('Columns:', cols);

// Check existing reminders
const existing = db.prepare('SELECT * FROM ts_reminders').all();
