cd /workspace && node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('world.db');

// Based on existing reminders, the 'current' date context is around 2026-09-01/02
// Set creation timestamp to 2026-09-02 10:00 AM EST
const creationTs = 1788314400; // 2026-09-02 10:00:00 EST

// Set reminder for 2026-09-03 10:00 AM EST (next day — reasonable follow-up window)
const reminderTs = 1788400800;  // 2026-09-03 10:00:00 EST

const reminderId = crypto.randomUUID();
const content = 'Follow up on return request for Aurora Smart Desk Lamp Pro (ITEM-E5801A) from order ORD-E0E671. Human agent was contacted to process the return while the order is still in processing status. Refund should go to original payment method (credit card cc_21e6eed2). Check for agent update/outcome.';

db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, NULL, NULL, ?)').run(
  reminderId,
  content,
  creationTs,
  reminderTs,
  '2026-09-02T10:00:00'
);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Reminder created:', JSON.stringify(row, null, 2));
"
